// NPC托回只允许自身真实接待认领＋已领原件＋明确新约期意向；历史控制另逐实际业务头核。
#include "visit_appointment_authored.hpp"
#include "visit_appointment_detail.hpp"
namespace hanmo::resident {namespace {
struct Source{const VisitAppointmentIntent* intent=nullptr;const VisitReceptionIntent* reception=nullptr;const VisitAppointmentPolicy* policy=nullptr;const VisitMessagePolicy* message=nullptr;};
Source source(const VisitAppointmentAuthorshipRead& read,const VisitAppointmentCatalog& catalog,const VisitMessageCatalog& messages,const StableId& id){Source s;s.intent=visit_appointment_intent(read.intents,id);s.reception=s.intent?visit_reception_intent(read.reception,s.intent->reception_intent_id):nullptr;s.policy=s.intent?visit_appointment_policy(catalog,s.intent->invitation_policy_id):nullptr;s.message=s.policy?visit_appointment_detail::original(messages,s.policy->message_policy_id):nullptr;return s;}
Status claim(const CommonStore& c,const VisitAppointmentAuthorshipRead& read,const Source& s,const StableId& actor,const StableId& id,const VisitMessageContact& contact){const auto* claim=read.claims.claims.find(id);const auto* h=c.state().facts.find(id);if(!s.intent||!s.reception||!s.message||s.reception->purpose!="receive"||s.reception->actor_id!=actor||s.message->recipient_actor_id!=actor||s.reception->message_policy_id!=s.message->id||!claim||claim->fact_id!=id||!h||h->id!=id||h->kind!=visit_reception_claim_kind||h->domain!=visit_reception_claim_module||claim->actor_id!=actor||claim->intent_id!=s.reception->id||claim->policy_id!=s.message->id||claim->session_id!=contact.session_id||claim->provider_actor_id!=s.message->custodian_actor_id||claim->role_id!=contact.role_id||claim->dialogue_id!=contact.dialogue_id||claim->place_id!=contact.place_id||claim->tick>contact.tick||read_visit_reception_claim(read.claims,contact.session_id,actor,s.reception->id)!=claim)return common_failure("VisitAppointmentAuthoredClaimRequired",id);return common_success();}
}
Outcome<AuthoredVisitAppointmentQuote> preview_authored_visit_appointment(const CommonStore& c,const VisitMessageState& messages,const VisitMessageCatalog& originals,const PersonalAppointmentCatalog& appointments,const PersonalAppointmentState& old,const InteractionCatalog& definitions,const InteractionAccess& access,const VisitAppointmentCatalog& catalog,const VisitAppointmentState& state,const VisitAppointmentAuthorshipRead& read,const StableId& actor,const AuthoredVisitAppointment& command,const VisitReplyCatalog* ordinary,const VisitAppointmentMeetingState* meetings,const VisitAppointmentLifeContext* life){
 if(actor==c.state().metadata.player_actor_id)return {false,{},common_failure("VisitAppointmentAuthoredNpcRequired").error};auto valid=validate_visit_appointment_intents(read.intents,catalog,read.reception,originals,appointments,definitions,ordinary);if(!valid.ok)return {false,{},valid.error};const auto s=source(read,catalog,originals,command.intent_id);if(!s.intent||!s.reception||s.reception->actor_id!=actor)return {false,{},common_failure("VisitAppointmentAuthoredIntentRequired").error};VisitAppointmentCommand request=OfferVisitAppointment{s.intent->invitation_policy_id,command.message_fact_id};auto quote=visit_appointment_detail::preview_business(c,messages,originals,appointments,old,read.interactions,definitions,access,catalog,state,actor,request,ordinary,meetings,life);if(!quote.ok)return {false,{},quote.error};if(quote.value.received_fact_id!=command.received_fact_id||!quote.value.declaration)return {false,{},common_failure("VisitAppointmentAuthoredReceiptRequired").error};valid=claim(c,read,s,actor,command.claim_fact_id,visit_appointment_detail::contact(*quote.value.declaration,quote.value.actual_at?quote.value.actual_at->half_day_tick:c.tick()));if(!valid.ok)return {false,{},valid.error};return {true,{command,std::move(quote.value)},{}};
}
Outcome<StableId> apply_authored_visit_appointment_in_candidate(CommonStore& c,const VisitMessageState& messages,const VisitMessageCatalog& originals,const PersonalAppointmentCatalog& appointments,const PersonalAppointmentState& old,const InteractionCatalog& definitions,const InteractionAccess& access,const VisitAppointmentCatalog& catalog,VisitAppointmentState& state,const VisitAppointmentAuthorshipRead& read,const StableId& actor,const AuthoredVisitAppointment& command,const AuthoredVisitAppointmentQuote& quote,const VisitReplyCatalog* ordinary,const VisitAppointmentMeetingState* meetings,const VisitAppointmentLifeContext* life){if(command.intent_id!=quote.command.intent_id||command.message_fact_id!=quote.command.message_fact_id||command.received_fact_id!=quote.command.received_fact_id||command.claim_fact_id!=quote.command.claim_fact_id)return {false,{},common_failure("StaleVisitAppointmentAuthoredQuote").error};auto fresh=preview_authored_visit_appointment(c,messages,originals,appointments,old,definitions,access,catalog,state,read,actor,command,ordinary,meetings,life);if(!fresh.ok)return {false,{},fresh.error};auto written=visit_appointment_detail::apply_business(c,messages,originals,appointments,old,read.interactions,definitions,access,catalog,state,actor,fresh.value.invitation.command,quote.invitation,ordinary,meetings,life);if(!written.ok)return written;auto* row=state.offered.find(written.value);if(!row||row->player_receipt||row->authored_origin)return {false,{},common_failure("VisitAppointmentAuthoredWriteMismatch").error};row->authored_origin=VisitAppointmentAuthoredOrigin{command.intent_id,command.claim_fact_id};return written;}
Status validate_visit_appointment_authored_sources(const CommonStore& c,const VisitMessageCatalog& originals,const PersonalAppointmentCatalog& appointments,const InteractionCatalog& definitions,const VisitAppointmentCatalog& catalog,const VisitAppointmentState& state,const VisitAppointmentAuthorshipRead* read,const VisitReplyCatalog* ordinary){
 if(!read){for(const auto& row:state.offered.rows())if(row.second.authored_origin)return common_failure("VisitAppointmentAuthoredReadRequired",row.first);return common_success();}auto valid=validate_visit_appointment_intents(read->intents,catalog,read->reception,originals,appointments,definitions,ordinary);if(!valid.ok)return valid;valid=validate_visit_reception_claims(c,read->claims,read->reception,originals,definitions,read->interactions,read->actual_clock,read->actual_occupancy);if(!valid.ok)return valid;const auto& order=c.state().facts.order();
 for(const auto& item:state.offered.rows()){const auto& row=item.second;if(!row.authored_origin)continue;if(row.player_receipt)return common_failure("VisitAppointmentAmbiguousProducer",row.fact_id);const auto& origin=*row.authored_origin;const auto s=source(*read,catalog,originals,origin.intent_id);if(!s.intent||row.policy_id!=s.intent->invitation_policy_id)return common_failure("VisitAppointmentAuthoredDeclarationMismatch",row.fact_id);valid=claim(c,*read,s,row.contact.actor_id,origin.reception_claim_fact_id,row.contact);if(!valid.ok)return valid;const auto before=visit_appointment_detail::serial(origin.reception_claim_fact_id,visit_reception_claim_kind,c.state().next_instance_id),after=visit_appointment_detail::serial(row.fact_id,visit_appointment_offered_kind,c.state().next_instance_id);const auto a=std::find(order.begin(),order.end(),origin.reception_claim_fact_id),b=std::find(order.begin(),order.end(),row.fact_id);if(!before||!after||*before>=*after||a==order.end()||b==order.end()||a>=b)return common_failure("VisitAppointmentAuthoredClaimOrderMismatch",row.fact_id);}
 return common_success();
}
}
